import { StrictMode, useState } from "react";
import { createRoot } from "react-dom/client";
import { AlbumEngine, LAYOUT_TYPES, type LayoutType } from "../src";
import "../src/styles.css";
import { demoAlbum } from "./album";
import "./demo.css";

const LABELS: Record<LayoutType, string> = {
  PAGE_FLIP: "ספר",
  SLIDER: "מצגת",
  GRID: "רשת",
};

/**
 * `?repeat=4` stacks the sample greetings four times over. A handful of
 * greetings is not a fair test of the book: several of the layout's decisions
 * only bite once there are enough split greetings for the spacer leaves to
 * accumulate.
 */
function repeatPages(album: typeof demoAlbum, times: number) {
  if (times <= 1) return album;

  const pages = Array.from({ length: times }, (_, round) =>
    album.pages.map((page, i) => ({
      ...page,
      id: `${page.id}-r${round}`,
      order: round * album.pages.length + i,
    })),
  ).flat();

  return { ...album, pages };
}

function Demo() {
  const [layoutType, setLayoutType] = useState<LayoutType>("PAGE_FLIP");
  const repeat = Number(
    new URLSearchParams(window.location.search).get("repeat") ?? 1,
  );
  const album = repeatPages(demoAlbum, Number.isFinite(repeat) ? repeat : 1);

  return (
    <div className="demo">
      <header className="demo__bar">
        <h1 className="demo__title">@sassoninc/album-engine-core</h1>
        <div className="demo__layouts" role="group" aria-label="Layout">
          {LAYOUT_TYPES.map((layout) => (
            <button
              key={layout}
              type="button"
              onClick={() => setLayoutType(layout)}
              aria-pressed={layout === layoutType}
              className="demo__layout"
            >
              {LABELS[layout]}
            </button>
          ))}
        </div>
      </header>

      <main className="demo__stage">
        <AlbumEngine
          key={layoutType}
          albumData={{ ...album, layoutType }}
          viewVariant="full"
        />
      </main>
    </div>
  );
}

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <Demo />
  </StrictMode>,
);
